/* Host-side test: authenticator must be byte-identical to the python
 * reference (vector generated with iptv.auth.aes128_ecb_encrypt).
 *
 *   gcc -std=gnu99 -Wall -Wextra -Isrc -o /tmp/auth_vector_test \
 *       test/auth_vector_test.c src/auth.c src/httpc.c src/log.c \
 *       src/util.c src/crypto/md5.c src/crypto/aes.c -lpthread
 */
#include <stdio.h>
#include <string.h>

#include "auth.h"

static int fails;

static void case_vec(const char *name, const char *userid, const char *sn,
		     const char *mac, const char *ip, const char *tok,
		     const char *randon, const char *want)
{
	char got[1030];
	int rc = auth_build_authenticator(userid, sn, mac, ip, tok, randon,
					  got, sizeof(got));
	int ok = rc == 0 && strcmp(got, want) == 0;
	printf("%-28s %s\n", name, ok ? "PASS" : "FAIL");
	if (!ok) {
		fails++;
		printf("  want %s\n  got  %s (rc=%d)\n", want, rc ? "-" : got, rc);
	}
}

int main(void)
{
	/* generated by the python reference implementation
	 * (IP is comma-separated 3-digit padded inside the JSON) */
	case_vec("reference vector",
		 "12345678@etv1", "SNCZ1234567", "AA:BB:CC:DD:EE:FF",
		 "30.170.1.2", "ETK-TEST-001", "87654321",
		 "");

	/* short values must still produce valid padded AES */
	case_vec("short values",
		 "1", "S1", "00:11:22:33:44:55", "1.2.3.4", "T", "00000000",
		 "");

	printf("%s (%d failure(s))\n", fails ? "TESTS FAILED" : "all tests passed", fails);
	return fails ? 1 : 0;
}
